SELECT product_id, CASE WHEN YEAR(sale_date) < 2024 THEN 'before_2024' WHEN YEAR(sale_date) = 2024 THEN '2024' ELSE 'after_2024' END AS sale_cohort, MIN(revenue) AS min_revenue FROM store_sales WHERE revenue > 2800 AND store_id = 5 GROUP BY product_id, CASE WHEN YEAR(sale_date) < 2024 THEN 'before_2024' WHEN YEAR(sale_date) = 2024 THEN '2024' ELSE 'after_2024' END HAVING MIN(revenue) > 2100 ORDER BY min_revenue DESC;
